import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"Direct Memory Access","description":"","frontmatter":{"search":{"exclude":true}},"headers":[],"relativePath":"d/ad/direct-memory-access.md","filePath":"d/ad/direct-memory-access.md","lastUpdated":1781102819000}`),a={name:`d/ad/direct-memory-access.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/ad/direct-memory-access.md for this page in Markdown format</div><h1 id="direct-memory-access" tabindex="-1">Direct Memory Access <a class="header-anchor" href="#direct-memory-access" aria-label="Permalink to “Direct Memory Access”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>Direct Memory Access (DMA) enables hardware devices such as network cards or USB controllers to access the system&#39;s main memory directly without involving the CPU. This allows faster data transfers.</p><p>In a DMA attack, an attacker uses physical or remote access to a target system and takes advantage of the DMA capabilities to access the RAM directly. This access allows the attacker to bypass traditional security measures such as operating system permissions or encryption and potentially gain unauthorized access to sensitive data or compromise the system&#39;s integrity.</p><p>There are two main types of DMA attacks:</p><ol><li>DMA read attacks: The attacker gains access to the system&#39;s memory and can read sensitive information from memory, such as encryption keys, passwords, or confidential data. The attacker can then use this information for unauthorized purposes.</li></ol><p>2 DMA write attacks: The attacker injects malicious data or code into the system&#39;s memory and overwrites potentially critical data or alters the system&#39;s behavior. This can lead to privilege escalation, malware injection, or changes to system settings.</p><p>DMA attacks can be carried out in various ways, including physical access to the target system, compromised peripherals, or exploiting vulnerabilities in the system firmware or drivers. Some examples of DMA attack vectors are FireWire, Thunderbolt, PCI Express, or PCMCIA interfaces.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><p>Activate the Windows function &quot;Kernel DMA Protection&quot; to protect against DMA attacks.</p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};